  ('22745ddb-1542-541c-98a8-ae23ad8c0204', '22222222-2222-2222-2222-222222222215', 'short', '前𝑛项和𝑆𝑛= 𝐴𝑛2 + 𝐵𝑛 ⇔ 数列{𝑎𝑛}是等差数列.', null, '', '', '数学/第5章 数列(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 6, null),
  ('339630f5-2e71-58bb-bd1e-b9beef6fa83e', '22222222-2222-2222-2222-222222222215', 'short', '若𝑚, 𝑛, 𝑙, 𝑘, (𝑘∈𝑁+)，且𝑚+ 𝑛= 𝑙+ 𝑘，则𝑎𝑚+ 𝑎𝑛= 𝑎𝑙+ 𝑎𝑘. 特别地，若𝑚+ 𝑛= 2𝑝，则𝑎𝑚+ 𝑎𝑛= 𝑎𝑝+ 𝑎𝑝= 2𝑎𝑝.', null, '', '', '数学/第5章 数列(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 7, null),
  ('dc50ba8b-3267-53dd-9ad2-f8bbe4a491a6', '22222222-2222-2222-2222-222222222215', 'short', '等比数列：𝑎𝑛= 𝑎1𝑞𝑛−1 = 𝑎𝑚𝑞𝑛−𝑚.', null, '', '', '数学/第5章 数列(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 8, null),
  ('eab14697-9030-51aa-b6dd-eabbb0dfdce6', '22222222-2222-2222-2222-222222222215', 'short', '等比数列：𝑆𝑛= { 𝑛𝑎1, 𝑞= 1, 𝑎1(1−𝑞𝑛) 1−𝑞 , 𝑞≠0 且𝑞≠1. 知新 主讲人：十一老师 现在是网络设备测试时间，课程将准时开始，请大家耐心等待 你的坚持，终将美好！ 18 四、等比数列{𝒂𝒏}的重要性质', null, '', '', '数学/第5章 数列(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 1, true, 9, null),
  ('ac4f0bc6-4d32-5c3e-a686-e80311e3717a', '22222222-2222-2222-2222-222222222215', 'short', '等比数列奇数项同号，偶数项也同号.', null, '', '', '数学/第5章 数列(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 2, true, 10, null),
  ('27261d74-ae10-5eea-a365-5abadeb7b601', '22222222-2222-2222-2222-222222222215', 'short', '若𝑎, 𝑏, 𝑐成等比数列，则称𝑏是𝑎, 𝑐的等比中项，且𝑏2 = 𝑎𝑐.', null, '', '', '数学/第5章 数列(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 2, true, 11, null),
  ('5be2eda5-8665-520b-bee1-048db16e21fb', '22222222-2222-2222-2222-222222222215', 'short', '若𝑚, 𝑛, 𝑙, 𝑘, (𝑘∈𝑁+)，且𝑚+ 𝑛= 𝑙+ 𝑘，则𝑎𝑚⋅𝑎𝑛= 𝑎𝑙⋅𝑎𝑘. 特别地，若𝑚+ 𝑛= 2𝑝，则𝑎𝑚⋅𝑎𝑛= 𝑎𝑝⋅𝑎𝑝= (𝑎𝑝)2（☆☆☆）. 简记为，若项数相等，则项积相等（可拓展至多项）. 推导： 𝑎𝑚= 𝑎1𝑞𝑚−1，𝑎𝑛= 𝑎1𝑞𝑛−1，𝑎𝑙= 𝑎1𝑞𝑙−1，𝑎𝑘= 𝑎1𝑞𝑘−1 𝑎𝑚⋅𝑎𝑛= 𝑎1𝑞𝑚−1 ⋅𝑎1𝑞𝑛−1 = 𝑎1 2𝑞𝑚+𝑛−2 = 𝑎1 2 ⋅𝑞−2 ⋅𝑞𝑚+𝑛 𝑎𝑙⋅𝑎𝑘= 𝑎1𝑞𝑙−1 ⋅𝑎1𝑞𝑘−1 = 𝑎1 2𝑞𝑙+𝑘−2 = 𝑎1 2 ⋅𝑞−2 ⋅𝑞𝑙+𝑘 两式对比：区别在𝑞𝑚+𝑛与𝑞𝑙+𝑘 所以𝑚+ 𝑛= 𝑙+ 𝑘，则有𝑎𝑚⋅𝑎𝑛= 𝑎𝑙⋅𝑎𝑘.', null, '', '', '数学/第5章 数列(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 2, true, 12, null),
  ('fe19eb2b-b0fc-5d7f-b334-8595e29fe9f1', '22222222-2222-2222-2222-222222222215', 'short', '若数列{𝑎𝑛}是公比为𝑞1的等比数列，若数列{𝑏𝑛}是公比为𝑞2的等比数 列，则{𝜆1𝑎𝑛∙𝜆2𝑏𝑛}(𝜆1, 𝜆2为常数)也是等比数列且公比为𝑞1 ∙𝑞2. 设等比数列𝑎𝑛= 𝑎𝑛−1𝑞1，𝑏𝑛= 𝑏𝑛−1𝑞2 𝜆1𝑎𝑛⋅𝜆2𝑏𝑛= 𝜆1𝑎𝑛−1𝑞1 ∙𝜆2𝑏𝑛−1𝑞2 = 𝜆1𝑎𝑛−1 ∙𝜆2𝑏𝑛−1 ∙(𝑞1𝑞2). 你的坚持，终将美好！ 19', null, '', '', '数学/第5章 数列(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 2, true, 13, null),
