  ('fc45d369-72fc-59ed-9527-fbd2af3c5274', '22222222-2222-2222-2222-222222222215', 'mcq', '等比数列{𝑎𝑛},𝑎3, 𝑎8是方程3𝑥2 + 2𝑥−18 = 0的两个根,则𝑎4𝑎7=( ).', '[{"key": "A", "text": "−9"}, {"key": "B", "text": "−8"}, {"key": "C", "text": "−6"}, {"key": "D", "text": "6"}, {"key": "E", "text": "8"}]'::jsonb, '', '', '数学/第5章 数列(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 15, null),
